package binding

import (
	"net/http"
	"net/textproto"
	"reflect"
)

type headerBinding struct{}

func (headerBinding) Name() string {
	return "header"
}

func (headerBinding) Bind(req *http.Request, obj interface{}) error {
	if err := mapHeader(obj, req.Header); err != nil {
		return err
	}

	return validate(obj)
}

func mapHeader(ptr interface{}, header http.Header) error {
	return mappingByPtr(ptr, headerSource(header), "header")
}

type headerSource http.Header

var _ setter = headerSource(nil)

func (header headerSource) TrySet(value reflect.Value, field reflect.StructField, tagValue string, opt setOptions) (isSetted bool, err error) {
	return setByForm(value, field, http.Header(header), textproto.CanonicalMIMEHeaderKey(tagValue), opt)
}

